<script>
(function(){
  "use strict";
  const COLS = 24, ROWS = 24;
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const CELL = canvas.width / COLS;

  // DOM
  const elScore = document.getElementById('score');
  const elBest  = document.getElementById('best');
  const elSpeed = document.getElementById('speed');
  const overlay = document.getElementById('overlay');
  const ovBadge = document.getElementById('ovBadge');
  const ovTitle = document.getElementById('ovTitle');
  const ovSub   = document.getElementById('ovSub');
  const ovScore = document.getElementById('ovScore');
  const ovBtn   = document.getElementById('ovBtn');
  const btnStart = document.getElementById('btnStart');
  const btnPause = document.getElementById('btnPause');
  const btnRestart = document.getElementById('btnRestart');
  const dpad = document.getElementById('dpad');

  // state
  let snake, dir, nextDir, food, bonus, bonusTimer;
  let score, best, speed, state; // state: 'ready'|'playing'|'paused'|'over'
  let acc = 0, last = 0, rafId = null;
  let particles = [];
  let shake = 0;
  let foodPulse = 0;

  const BASE_INTERVAL = 150;
  const MIN_INTERVAL = 65;

  function loadBest(){ try{ return parseInt(localStorage.getItem('snake_best')||'0',10)||0; }catch(e){ return 0; } }
  function saveBest(v){ try{ localStorage.setItem('snake_best', String(v)); }catch(e){} }

  function reset(){
    const cx = Math.floor(COLS/2), cy = Math.floor(ROWS/2);
    snake = [ {x:cx-1,y:cy}, {x:cx-2,y:cy}, {x:cx-3,y:cy} ];
    dir = {x:1,y:0};
    nextDir = {x:1,y:0};
    score = 0;
    speed = 1;
    bonus = null; bonusTimer = 0;
    particles = [];
    shake = 0;
    placeFood();
    updateHud();
  }

  function placeFood(){
    let p, guard = 0;
    do{
      p = { x: Math.floor(Math.random()*COLS), y: Math.floor(Math.random()*ROWS) };
      guard++;
    }while(snake.some(s=>s.x===p.x&&s.y===p.y) && guard<1000);
    food = p;
  }

  function maybeBonus(){
    if(bonus) return;
    if(Math.random() < 0.12){
      let p, guard=0;
      do{
        p = { x: Math.floor(Math.random()*COLS), y: Math.floor(Math.random()*ROWS) };
        guard++;
      }while((snake.some(s=>s.x===p.x&&s.y===p.y) || (food.x===p.x&&food.y===p.y)) && guard<1000);
      bonus = p;
      bonusTimer = 12; // ticks to live
    }
  }

  function setDir(nx, ny){
    // prevent reversing
    if(nx === -dir.x && ny === -dir.y) return;
    nextDir = {x:nx, y:ny};
  }

  function step(){
    dir = nextDir;
    const head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };

    // wall collision
    if(head.x < 0 || head.x >= COLS || head.y < 0 || head.y >= ROWS){
      return gameOver();
    }
    // self collision (tail will move unless eating, so check against body minus last)
    const willEat = (head.x===food.x && head.y===food.y) || (bonus && head.x===bonus.x && head.y===bonus.y);
    const bodyToCheck = willEat ? snake : snake.slice(0, snake.length-1);
    if(bodyToCheck.some(s=>s.x===head.x && s.y===head.y)){
      return gameOver();
    }

    snake.unshift(head);

    if(head.x===food.x && head.y===food.y){
      score += 10;
      spawnBurst(head.x, head.y, '#ff6a4d', 14);
      bumpScore();
      placeFood();
      maybeBonus();
      // speed up
      speed = Math.min(12, 1 + Math.floor(score/50));
      updateHud();
    } else if(bonus && head.x===bonus.x && head.y===bonus.y){
      score += 50;
      spawnBurst(head.x, head.y, '#ffcf5c', 22);
      bumpScore();
      bonus = null;
      updateHud();
    } else {
      snake.pop();
    }

    if(bonus){ bonusTimer--; if(bonusTimer<=0) bonus = null; }
  }

  function gameOver(){
    state = 'over';
    shake = 14;
    spawnBurst(snake[0].x, snake[0].y, '#ff6a4d', 26);
    if(score > best){ best = score; saveBest(best); }
    updateHud();
    showOverlay('over');
  }

  // ---- HUD ----
  function updateHud(){
    elScore.textContent = score;
    elBest.textContent = best;
    elSpeed.textContent = speed;
  }
  function bumpScore(){
    elScore.classList.remove('pop');
    void elScore.offsetWidth;
    elScore.classList.add('pop');
  }

  // ---- Overlay ----
  function showOverlay(kind){
    overlay.classList.remove('hidden');
    ovScore.style.display = 'none';
    if(kind==='ready'){
      ovBadge.textContent = 'READY'; ovBadge.className='ov-badge';
      ovTitle.innerHTML = '准备<span class="hl">出发</span>';
      ovSub.textContent = '用方向键或 WASD 控制小蛇，吃掉食物不断变长，别撞到自己或墙壁！';
      ovBtn.textContent = '开始游戏';
    } else if(kind==='paused'){
      ovBadge.textContent = 'PAUSED'; ovBadge.className='ov-badge';
      ovTitle.innerHTML = '已<span class="hl">暂停</span>';
      ovSub.textContent = '休息一下，随时继续。';
      ovBtn.textContent = '继续';
    } else if(kind==='over'){
      ovBadge.textContent = 'GAME OVER'; ovBadge.className='ov-badge danger';
      ovTitle.innerHTML = '游戏<span class="hl">结束</span>';
      ovSub.textContent = '小蛇撞上了障碍，再来一局挑战更高分吧！';
      ovScore.style.display = 'block';
      ovScore.innerHTML = '本局 <span>'+score+'</span> · 最高 <span>'+best+'</span>';
      ovBtn.textContent = '再来一局';
    }
  }
  function hideOverlay(){ overlay.classList.add('hidden'); }

  // ---- Controls ----
  function start(){
    if(state==='playing') return;
    if(state==='over' || state==='ready'){ reset(); }
    state = 'playing';
    hideOverlay();
    btnPause.textContent = '暂停';
    last = performance.now();
    acc = 0;
    if(!rafId) rafId = requestAnimationFrame(loop);
  }
  function pause(){
    if(state!=='playing') return;
    state = 'paused';
    showOverlay('paused');
    btnPause.textContent = '继续';
  }
  function togglePause(){
    if(state==='playing') pause();
    else if(state==='paused') start();
    else start();
  }
  function restart(){
    reset();
    state = 'playing';
    hideOverlay();
    btnPause.textContent = '暂停';
    last = performance.now(); acc = 0;
    if(!rafId) rafId = requestAnimationFrame(loop);
  }

  // ---- Particles ----
  function spawnBurst(cx, cy, color, n){
    const px = (cx+0.5)*CELL, py = (cy+0.5)*CELL;
    for(let i=0;i<n;i++){
      const a = Math.random()*Math.PI*2;
      const sp = 1 + Math.random()*3.2;
      particles.push({
        x:px, y:py,
        vx:Math.cos(a)*sp, vy:Math.sin(a)*sp,
        life:1, decay:0.02+Math.random()*0.03,
        size:2+Math.random()*3, color
      });
    }
  }
  function updateParticles(){
    for(let i=particles.length-1;i>=0;i--){
      const p = particles[i];
      p.x += p.vx; p.y += p.vy;
      p.vx *= 0.94; p.vy *= 0.94;
      p.vy += 0.05;
      p.life -= p.decay;
      if(p.life<=0) particles.splice(i,1);
    }
  }

  // ---- Render ----
  function roundRect(x,y,w,h,r){
    ctx.beginPath();
    ctx.moveTo(x+r,y);
    ctx.arcTo(x+w,y,x+w,y+h,r);
    ctx.arcTo(x+w,y+h,x,y+h,r);
    ctx.arcTo(x,y+h,x,y,r);
    ctx.arcTo(x,y,x+w,y,r);
    ctx.closePath();
  }

  function draw(){
    ctx.clearRect(0,0,canvas.width,canvas.height);

    // shake
    ctx.save();
    if(shake>0){
      const s = shake;
      ctx.translate((Math.random()-0.5)*s, (Math.random()-0.5)*s);
      shake *= 0.82; if(shake<0.4) shake=0;
    }

    // board bg
    const g = ctx.createLinearGradient(0,0,canvas.width,canvas.height);
    g.addColorStop(0,'#0c201a'); g.addColorStop(1,'#081511');
    ctx.fillStyle = g;
    ctx.fillRect(0,0,canvas.width,canvas.height);

    // grid
    ctx.strokeStyle = 'rgba(198,242,78,0.05)';
    ctx.lineWidth = 1;
    for(let i=1;i<COLS;i++){
      ctx.beginPath(); ctx.moveTo(i*CELL,0); ctx.lineTo(i*CELL,canvas.height); ctx.stroke();
    }
    for(let j=1;j<ROWS;j++){
      ctx.beginPath(); ctx.moveTo(0,j*CELL); ctx.lineTo(canvas.width,j*CELL); ctx.stroke();
    }

    // food
    drawFood(food, '#ff6a4d', '#ffd0c0', foodPulse);
    // bonus
    if(bonus){
      const blink = bonusTimer<=4 ? (Math.floor(performance.now()/120)%2===0) : true;
      if(blink) drawFood(bonus, '#ffcf5c', '#fff2c0', foodPulse*1.3, true);
    }

    // snake
    drawSnake();

    // particles
    for(const p of particles){
      ctx.globalAlpha = Math.max(0,p.life);
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(p.x,p.y,p.size,0,Math.PI*2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;

    ctx.restore();
  }

  function drawFood(f, main, light, pulse, star){
    const cx = (f.x+0.5)*CELL, cy = (f.y+0.5)*CELL;
    const r = CELL*0.32 * (1 + Math.sin(pulse)*0.12);
    // glow
    const glow = ctx.createRadialGradient(cx,cy,0,cx,cy,r*2.4);
    glow.addColorStop(0, main+'aa'); glow.addColorStop(1, main+'00');
    ctx.fillStyle = glow;
    ctx.beginPath(); ctx.arc(cx,cy,r*2.4,0,Math.PI*2); ctx.fill();
    // body
    const bg = ctx.createRadialGradient(cx-r*0.4,cy-r*0.4,r*0.2,cx,cy,r);
    bg.addColorStop(0, light); bg.addColorStop(1, main);
    ctx.fillStyle = bg;
    ctx.beginPath(); ctx.arc(cx,cy,r,0,Math.PI*2); ctx.fill();
    // stem
    ctx.strokeStyle = '#8fd63a'; ctx.lineWidth = 2; ctx.lineCap='round';
    ctx.beginPath(); ctx.moveTo(cx,cy-r); ctx.quadraticCurveTo(cx+r*0.5,cy-r*1.6,cx+r*0.2,cy-r*1.9); ctx.stroke();
    // shine
    ctx.fillStyle = 'rgba(255,255,255,.7)';
    ctx.beginPath(); ctx.arc(cx-r*0.35,cy-r*0.35,r*0.22,0,Math.PI*2); ctx.fill();
  }

  function drawSnake(){
    const n = snake.length;
    for(let i=n-1;i>=0;i--){
      const s = snake[i];
      const t = n>1 ? i/(n-1) : 0; // 0 head -> 1 tail
      const x = s.x*CELL, y = s.y*CELL;
      const pad = 1.5 + t*1.5;
      const size = CELL - pad*2;
      const rx = x+pad, ry = y+pad;
      const rad = i===0 ? size*0.42 : size*0.34;

      // color gradient head->tail
      const c1 = i===0 ? '#d8ff6a' : '#c6f24e';
      const c2 = i===0 ? '#a9e03a' : '#7fbf2e';
      const grad = ctx.createLinearGradient(rx,ry,rx+size,ry+size);
      grad.addColorStop(0,c1); grad.addColorStop(1,c2);

      // head glow
      if(i===0){
        const cx = x+CELL/2, cy = y+CELL/2;
        const glow = ctx.createRadialGradient(cx,cy,0,cx,cy,CELL*1.1);
        glow.addColorStop(0,'rgba(198,242,78,.45)'); glow.addColorStop(1,'rgba(198,242,78,0)');
        ctx.fillStyle = glow;
        ctx.beginPath(); ctx.arc(cx,cy,CELL*1.1,0,Math.PI*2); ctx.fill();
      }

      ctx.fillStyle = grad;
      roundRect(rx,ry,size,size,rad);
      ctx.fill();

      // subtle top highlight
      ctx.fillStyle = 'rgba(255,255,255,.14)';
      roundRect(rx+2,ry+2,size-4,size*0.4,rad*0.7);
      ctx.fill();
    }

    // eyes on head
    const h = snake[0];
    const hx = h.x*CELL, hy = h.y*CELL;
    const cx = hx+CELL/2, cy = hy+CELL/2;
    const ex = dir.x, ey = dir.y;
    const off = CELL*0.16;
    const perpX = -ey, perpY = ex;
    const eyeR = CELL*0.11;
    for(const sgn of [1,-1]){
      const exx = cx + ex*off + perpX*off*sgn;
      const eyy = cy + ey*off + perpY*off*sgn;
      ctx.fillStyle = '#fff';
      ctx.beginPath(); ctx.arc(exx,eyy,eyeR,0,Math.PI*2); ctx.fill();
      ctx.fillStyle = '#0a1a15';
      ctx.beginPath(); ctx.arc(exx+ex*eyeR*0.4, eyy+ey*eyeR*0.4, eyeR*0.5,0,Math.PI*2); ctx.fill();
    }
  }

  // ---- Loop ----
  function loop(now){
    rafId = requestAnimationFrame(loop);
    const dt = now - last; last = now;
    foodPulse += dt*0.006;

    if(state==='playing'){
      const interval = Math.max(MIN_INTERVAL, BASE_INTERVAL - (speed-1)*9);
      acc += dt;
      let guard = 0;
      while(acc >= interval && guard<5){
        step();
        acc -= interval;
        guard++;
        if(state!=='playing') break;
      }
    }
    updateParticles();
    draw();
  }

  // ---- Input ----
  const keyMap = {
    ArrowUp:[0,-1], KeyW:[0,-1],
    ArrowDown:[0,1], KeyS:[0,1],
    ArrowLeft:[-1,0], KeyA:[-1,0],
    ArrowRight:[1,0], KeyD:[1,0]
  };
  window.addEventListener('keydown', function(e){
    const k = e.code;
    if(k==='Space'){ e.preventDefault(); togglePause(); return; }
    if(k==='KeyR'){ e.preventDefault(); restart(); return; }
    if(k==='Enter'){ e.preventDefault(); if(state!=='playing') start(); return; }
    if(keyMap[k]){
      e.preventDefault();
      if(state==='ready' || state==='over'){ start(); }
      setDir(keyMap[k][0], keyMap[k][1]);
    }
  });

  btnStart.addEventListener('click', start);
  btnPause.addEventListener('click', togglePause);
  btnRestart.addEventListener('click', restart);
  ovBtn.addEventListener('click', function(){
    if(state==='over') restart();
    else start();
  });

  // d-pad
  const dirMap = { up:[0,-1], down:[0,1], left:[-1,0], right:[1,0] };
  dpad.querySelectorAll('button[data-dir]').forEach(function(b){
    const d = b.dataset.dir;
    const handler = function(e){
      e.preventDefault();
      if(state==='ready' || state==='over') start();
      setDir(dirMap[d][0], dirMap[d][1]);
    };
    b.addEventListener('pointerdown', handler);
  });

  // swipe on canvas
  let touchStart = null;
  canvas.addEventListener('touchstart', function(e){
    if(e.touches.length===1){
      touchStart = { x:e.touches[0].clientX, y:e.touches[0].clientY };
    }
  }, {passive:true});
  canvas.addEventListener('touchend', function(e){
    if(!touchStart) return;
    const t = e.changedTouches[0];
    const dx = t.clientX - touchStart.x;
    const dy = t.clientY - touchStart.y;
    touchStart = null;
    if(Math.abs(dx)<20 && Math.abs(dy)<20) return;
    if(Math.abs(dx) > Math.abs(dy)){
      if(state==='ready'||state==='over') start();
      setDir(dx>0?1:-1, 0);
    } else {
      if(state==='ready'||state==='over') start();
      setDir(0, dy>0?1:-1);
    }
  }, {passive:true});

  // init
  best = loadBest();
  reset();
  state = 'ready';
  showOverlay('ready');
  rafId = requestAnimationFrame(loop);
})();
</script>
